def merge(nums, left, mid, right):
    n1 = mid - left + 1
    n2 = right - mid
    L = [0] * n1
    R = [0] * n2

    for i in range(0, n1):
        L[i] = nums[left + i]

    for i in range(0, n2):
        R[i] = nums[mid + 1 + i]

    i, j, k = 0, 0, left

