def shortest_path(graph, visited, past, s, t):
    if s in visited:
        return -1
    if s == t:
        return 0

    visited.add(s)
    past.add(s)
    weight_to_past = 0
    for path in graph[s]:
        if path[0] in past:
            continue
        dist = shortest_path(graph, visited, past, path[0], t)
        if dist == -1:
            continue
        else:
            weight_to_past = dist
            past = copy(past)
            past.add(path[0])

    return weight_to_past + path[1]

