def solve(nums, k):
    # using heapq - stack
    nums_sorted = sorted(set(nums))
    stack = []
    index_max = 0
    # adding data to stack and slicing all the same
    # index_max is assigned by -1 directly, because that's how heapq works. If just is 1,
    # will get No such item: -1 - max heap
    for i in range(len(nums)):
        if len(nums_sorted) > i:
            stack.append(heapq.heappush(stack, (-nums_sorted[i], -i)))
            index_max = -stack[0][1]
        if len(stack) > k:
            if len(stack) > k:
                if stack[0][1] == index_max:
                    heapq.heappop(stack)
                else:
                    return stack[0][0]
    return stack[0][0]

