def recursive_binary(nums, k, min, max):
    """ Recursive binary search, does not count k in return range
    k is 1: the min value
    k = nums.len(): the max value"""
    if not len(nums): return -1
    if len(nums) == 1: return nums[0]
    if k == 1:
        return sorted(nums)[0]
    if k == len(nums):
        return sorted(nums)[len(nums)-1]
    mid = (min + max)/2    
    if nums[mid] == nums[min]:
        for i in range(len(nums)-1, mid-1, -1):
            if nums[i] == nums[min]:
                return recursive_binary(nums, k, min, i)

    if nums[mid] > nums[min]:
        return recursive_binary(nums, k, min, mid)
    if  nums[mid] <  nums[min]:
        return recursive_binary(nums, k, mid+1, max)

