def solve(nums, k):
    """arguments: nums is a list and k is an int"""
    def kth(array: list, l: int, r: int, k: int) -> int:
        """the recursive method"""
        if l == r:
            return array[l]
        m = (l + r) // 2
        left = kth(array, l, m, k)
        right = kth(array, m+1, r, k-(m-l+1))
        return left if left <= right else right

    return kth(nums,0,len(nums)-1,k)


