    start = min(nums)
    end = max(nums)
    height = end - start + 1
    middle = (start + end) // 2

    # start
    for i in range(len(nums)):
        if nums[i] == start:
            start = i
            break

    # ending is last element in list that matches column
    while nums[end] == end:
        end -= 1

