                if i not in nums[((start + 1):(middle + 1))]:
                    middle = start - 1 # shift index
                    # change element from equal element to middle to start 
                    nums[start], nums[middle] = middle, start
                    break # dont continue index search
                else:
                    middle += 1 # increase middle index
            continue # dont work until filtered middle position
        else:
            end = middle - 1
            for i in list(nums[middle:(end + 1)]):
                if i not in nums[((start + 1):(middle - 1))]:
