def solve(n, edges):
    """Return the number of connected components in a graph."""
    if edges is None or len(edges) == 0:
        return 0

    connectivity = {}

    for (node1, node2) in edges:
        if node1 not in connectivity:
            connectivity[node1] = set()
        if node2 not in connectivity:
            connectivity[node2] = set()

        connectivity[node1].add(node2)
        connectivity[node2].add(node1) 

    connected_components = 0
    for node in connectivity:
        if node in connectivity:
            connected_components += 1
            set_to_process = connectivity[node]
            union_to_run = set()
            while set_to_process:
                union_to_run = set.union(union_to_run, connectivity[set_to_process.pop()])
            merge_to_run = set.intersection(union_to_run, connectivity[node])
            while merge_to_run:
                union_to_run = set.union(union_to_run, merge_to_run)
                set_to_process = set.union(connectivity[set_to_process], set.union(connectivity[union_to_run], set_to_process))

    return connected_components

def solve(n, edges):
    """
    Parameters:
    n (int): the number of nodes
    edges (list(tuple(int, int))): the edge lists

    Returns:
    int: the number of nodes
    """
    graph = {}
    for e in edges:
        graph[e[0]] = list(graph.get(e[0], []) + [e[1]])
        graph[e[1]] = list(graph.get(e[1], []) + [e[0]])
    return len(set(elements[:n] for e in graph.values() for elements in e))


