            for idx, e in enumerate(eval("(" + str(edges) + ")"), start=1)]

    res = {1:[0],}
    added = {1}
    # Precompute IDs for all nodes in a connected component
    for a in adj[1]:
        for b in adj[a]:
            if b not in added:
                res[b+1]={1,}
                for c in adj[b]:
                    if c not in added:
                        res[c+1]={b+1,}
                added.add(b)
                added.update(res[b+1])
            if a in res[b+1]:
                sets = {1,
                        b+1,
                        *[v for v in res[b+1] if v not in res[a+1]]
                        }
                for idx in sets:
                    res[idx+1].update(res[b+1])
                for idx in res[b+1]:
                    for i in res[idx+1].difference(b+1):
                        res[i+1].add(idx+1)
                res.pop(b+1)
                added.add(a)
                added.update(res[a+1])
    return len(res)

