def solve_helper(row, col, grid, path_start, path_end, memoization_table):
    if path_start == path_end and grid[path_start[0]][path_start[1]] == '.':
        return [path_start]

    if path_start[0] not in range(row) or path_start[1] not in range(col) or grid[path_start[0]][path_start[1]] == '#':
        return None # invalid start (out of range, is #)

    if path_start in memoization_table and path_end not in memoization_table[path_start[0]]:
        return memoization_table[path_start[0]][path_start[1]]

    possible_cells = []
    if path_start[0] - 1 >= 0 and grid[path_start[0]-1][path_start[1]] != '#':
        possible_cells.append((path_start[0]-1, path_start[1]))

    if path_start[0] + 1 < row and grid[path_start[0]+1][path_start[1]] != '#':
        possible_cells.append((path_start[0]+1, path_start[1]))

    if path_start[1] - 1 >= 0 and grid[path_start[0]][path_start[1]-1] != '#':
        possible_cells.append((path_start[0], path_start[1]-1))

    if path_start[1] + 1 < col and grid[path_start[0]][path_start[1]+1] != '#':
        possible_cells.append((path_start[0], path_start[1]+1))

    cell = None
    for y in possible_cells:
        for n in y:
            path = solve_helper(row, col, grid, y, path_end, memoization_table)
            if path != None:
                cell = (y[0], y[1])
                solution = path[:]
                solution.append(cell)
                break

    if cell is None:
        return solution
    else:
        memoization_table[path_start[0]][path_start[1]] = solution
        return [path_end] + solution

