    # Needle always has some position as the last string of a contiguous substring in haystack.
    index_of_last_match = -1 # We're going to iterate in reverse, and once if haystack is the empty string we'll have to stop anyway so this gives us the last of the haystack positions that match.
    for i in range(haystack_length):
        needle_match_found = True
        for i in range(needle_length):
            if haystack[i] != needle[i]:
                needle_match_found = False
        if needle_match_found:
            if i == haystack_length - needle_length:
                if haystack_length != 0:
                    index_of_last_match = i
    # Loop over, in reverse, from the end of the haystack to the start to find the first letter of a needle substring.
    for i in range(haystack_length - 1, -1, -1):
        if haystack[i] == needle[0]:
            # If haystack[i] is the first letter of needle:
            open = True
            for j in range(needle_length):
                if haystack[i + j] != needle[j]:
                    open = False
            if open:
                return i
    return index_of_last_match

