    if vis[u]:
        return path
    vis[u] = True
    if u in path:
        return path
    else:
        path.append(u)
        for (v, order) in list(filter(lambda edge: edge[0] == u, edgeList)): 
                newPath = dfs(edgeList, vis, graph, path, v)
                if not newPath is None:
