    Return a list that contains every task exactly once and respects
    every pair. The list should be ordered; function returns an empty list
    if no valid order exists."""
    def dfs(course, done):
        # mark a course as in execution
        done[course] = True
        prereqs_of_course = prerequisites[course]
        for presq in prereqs_of_course:
            # if presq added back to the course, it means that presq will be add-backed later,
            #      otherwise, presq dependencies are not satisfied. So no valid order exists.
            if not done[presq]:
                if not dfs(presq, done):
                    return done
            # mark a course as done
        return done
    preorders = []
    for c, presq in enumerate(prerequisites):
        done = [False] * n
        if dfs(c, done):
            preorders.append(c)
    return preorders

