def solved(validBlocks, visit, n, visited, tasks, result):
    if len(tasks) == n:
        return True
    for v in validBlocks[visit]:
        if v not in visited:
            tasks.add(v)
            visited.add(v)
            result = solved(validBlocks, visit + 1, n, visited, tasks, result)
            if result:
                return result
            else:
                tasks.remove(v)
                visited.remove(v)

    return False

