def binarySearch(nums, target, low=None, high=None):
    mylow = low if low != None else 0
    myhigh = high if high != None else len(nums) -1
    # iteratively find the minimum value in the range [mylow,myhigh] that is >= target
    while mylow <= myhigh:
        mid = (low + high)//2
        if nums[mid] > target:
            high, myhigh = myhigh + 1, mid
        else:
            low, mylow, = mylow, mid

    return low

