            continue

        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]

