def solve(n, edges, s, t):
    """
    Finds the length of the shortest path from node s to node t in a directed weighted graph.

    Args:
        n: The number of nodes in the graph (nodes are numbered 0 to n-1).
        edges: A list of (u, v, w) tuples, where u is a node, v is a node, and w is the weight of the edge.
        s: The starting node.
        t: The target node.

    Returns:
        The length of the shortest path from s to t as an integer.
        Returns 0 if s equals t.
        Returns -1 if t cannot be reached from s.
    """
    if s == t:
        return 0

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n

    for _ in range(n):
        u = -1
        for v in range(n):
            if not visited[v] and (u == -1 or dist[v] < dist[u]):
                u = v

        if u == -1:
            break

        visited[u] = True

        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]

