def solve(n, edges):
    """
    Given an undirected graph, return the number of connected components.
    """
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for u, v in edges:
        union(u, v)

    count = 0
    for i in range(n):
        if parent[i] == i:
            count += 1

    return count

