def solve(n, edges):
    """
    Detects if an undirected graph contains a cycle.

    Args:
        n: The number of nodes in the graph (0-indexed).
        edges: A list of edges, where each edge is a pair of nodes [u, v].

    Returns:
        True if the graph contains a cycle, False otherwise.
    """

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n

    def dfs(node, parent):
        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, -1):
                return True

    return False

def solve(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [0] * n  # 0: uncolored, 1: red, 2: blue

    def is_bipartite(node, color):
        colors[node] = color
        for neighbor in adj[node]:
            if colors[neighbor] == 0:
                if not is_bipartite(neighbor, 3 - color):
                    return False
            elif colors[neighbor] == color:
                return False
        return True

    for i in range(n):
        if colors[i] == 0:
            if not is_bipartite(i, 1):
                return True

    return False

