def binary_search_min(arr):
    """
    Finds the minimum element in a sorted array using binary search.
    """
    low = 0
    high = len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    return arr[low]

def binary_search_max(arr):
    """
    Finds the maximum element in a sorted array using binary search.
    """
    low = 0
    high = len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] < arr[high]:
            low = mid + 1
        else:
            high = mid
    return arr[low]

def find_min_max(arr):
    """
    Finds the minimum and maximum values in an unsorted array.
    """
    min_val = arr[0]
    max_val = arr[0]
    for num in arr:
        if num < min_val:
            min_val = num
        if num > max_val:
