  adj = [[] for _ in range(n + 1)]
  for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

  visited = [False] * (n + 1)
  count = 0

  def dfs(node):
    visited[node] = True
    for neighbor in adj[node]:
      if not visited[neighbor]:
        dfs(neighbor)

  for i in range(1, n + 1):
    if not visited[i]:
      dfs(i)
      count += 1

  return count

