def solution(n: int, times: list[int], parties: list[list[int]]) -> int:
    """
    Given the number of people, the times each party takes to set up, and a list of parties,
    return the minimum time needed to set up all the parties.
    """
    graph = {}
    for time, party in zip(times, parties):
        if time not in graph:
            graph[time] = []
        graph[time].append(party)

    visited = set()
    count = 0

    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    for time in graph:
        if time not in visited:
            dfs(time)
            count += 1

    return count

def solve(n, edges):
    if n == 0:
        return 0
    if not edges:
        return 1 if n > 0 else 0

    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for u, v in edges:
        union(u, v)

    count = 0
    for i in range(n):
        if parent[i] == i:
            count += 1

    return count

