def avoid_wall(grid):
    rows = len(grid)
    cols = len(grid[0])

    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return -1

    q = [(0, 0)]
    visited = set()
    visited.add((0, 0))

    while q:
        r, c = q.pop(0)

        if r == rows - 1 and c == cols - 1:
            return 1

        # Possible moves: down and right
        moves = [(r + 1, c), (r, c + 1)]

        for nr, nc in moves:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and (nr, nc) not in visited:
                q.append((nr, nc))
                visited.add((nr, nc))

    return -1

